{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C10"],
      "claim": "Verapamil, the closest transferable analogue, has an absolute oral bioavailability of 34% in humans, clearly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "In normal subjects, verapamil absolute bioavailability was 22.0% after simultaneous IV and oral dosing, directly above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Noscapine, a related alkaloid with lower transferability, showed 30% absolute oral bioavailability in healthy volunteers, supporting the high category.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Praziquantel, despite hepatic disease conditions, had an oral bioavailability of 27.2%, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "One verapamil study in young men reported mean bioavailability of 19.4%, just below the threshold, indicating borderline first-pass metabolism; this is outweighed by multiple verapamil studies above 20%.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest analogue verapamil has absolute oral bioavailability mostly in the 20–24% range, with some values slightly below 20%, while noscapine and praziquantel show ~27–30%. The weight of transferable experimental evidence supports F ≥ 20%, so the prediction is high.",
  "evidence_gaps": [
    "No direct pharmacokinetic data are available for the query molecule itself.",
    "Verapamil bioavailability values straddle the 20% threshold, introducing borderline uncertainty.",
    "Effects of disease states, formulation, and first-pass metabolism on the query are not directly measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

